select task_id from dating_deduction_task where status='READY' and next_attempt_at <= current_timestamp
and pair_id=#{pairId}
order by task_id limit 100

mapper.update:
update dating_deduction_task set status=case when attempts>=4 then 'ERROR' else 'READY' end,
attempts=attempts+1,last_error=#{error},next_attempt_at=#{nextAttempt}
where task_id=#{id} and status='READY' and next_attempt_at <= current_timestamp
